-- Saved in-progress games: the latest HMAC-signed state token, keyed by the server-minted 128-bit game id.
-- Generated by drizzle-kit from db/schema.ts, then made idempotent by hand (IF NOT EXISTS; ENABLE ROW LEVEL SECURITY
-- is a no-op when already on), so it is safe to apply manually (Supabase SQL editor / apply_migration) AND to have
-- `npm run db:migrate` apply it again afterwards.
-- RLS on with NO policies: Supabase's Data API (anon / authenticated keys) can neither read nor write this table.
-- The server connects as the postgres role, which bypasses RLS. Do not put a NEXT_PUBLIC_ prefix on DATABASE_URL.
CREATE TABLE IF NOT EXISTS "saved_games" (
	"game_id" text PRIMARY KEY NOT NULL,
	"case_id" text NOT NULL,
	"state_token" text NOT NULL,
	"version" integer NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "saved_games" ENABLE ROW LEVEL SECURITY;
